def BACnetStack_SetObjectTypeCreatable(deviceInstance, objectType, creatable):
    """Allows objects of the specified object type to be created using the BACnet Create Object
    service.

    *Note1:** Device objects cannot be created using the Create Object service
    *Note2:** This function is only useful if the Create Object service is being supported

    SIDE EFFECT: creatable=true ALSO marks the object type as supported, so it appears in
    the device's
    Protocol_Object_Types_Supported. This is one-directional - creatable=false does NOT
    un-mark it, and
    the type stays advertised as supported.

    C declaration: bool BACnetStack_SetObjectTypeCreatable(const uint32_t deviceInstance,
    const uint16_t objectType, const bool creatable)

    Args:
        deviceInstance: (in) The instance of the device to allow the object to be created. The device
            must already exist. [const uint32_t deviceInstance]
        objectType: (in) The object type of the objects that can be created. See
            #CASBACnetStack::BACnetObjectType for more info. REJECTED: the Device object
            type, and any value at or above MAX_PROTOCOL_OBJECT_TYPES_SUPPORTED (65 at
            protocol revision 24; the constant varies by revision) - so proprietary object
            types cannot be made creatable through this function. [const uint16_t
            objectType]
        creatable: (in) True to make objects creatable, false to make objects not creatable.
            Recommended value: true [const bool creatable]

    Returns:
        True if successful. False if the device does not exist, objectType is rejected
        as above, or the stack was built without
        STACK_OPTION_DM_OCD_OBJECT_CREATION_AND_DELETION.
    """
    return _lib().BACnetStack_SetObjectTypeCreatable(deviceInstance, objectType, creatable)


def BACnetStack_RemoveDevice(deviceInstance):
    """Removes a device, and with it every object, property override and COV subscription that
    device owned.

    TWO TRAPS.

    1. REMOVING THE FIRST DEVICE RE-TARGETS THE MAIN-DEVICE APIs. Every function that takes
    no
    deviceInstance - the Channel, Group and Schedule configuration calls, the BACnet/SC UUID
    sync,
    the router and virtual-network checks - resolves "the device" as the FIRST device still
    registered. Remove the first one and the next device silently inherits all of them.
    2. A VIRTUAL DEVICE'S ROUTER MAPPING SURVIVES. No API unmaps a device from a virtual
    network, so
    after removing it BACnetStack_AddDeviceToVirtualNetwork rejects that same instance as a
    duplicate for the life of the process.

    C declaration: bool BACnetStack_RemoveDevice(const uint32_t deviceInstance)

    Args:
        deviceInstance: (in) The instance of the device to remove. [const uint32_t deviceInstance]

    Returns:
        True if the device existed and was removed, false if no such device exists.
    """
    return _lib().BACnetStack_RemoveDevice(deviceInstance)


def BACnetStack_RemoveObject(deviceInstance, objectType, objectInstance):
    """Removes an object from a device. The device must exist.

    This function will also return true if the object does not exist.

    RETURN SEMANTICS: false means, and only means, that the DEVICE does not exist. Every
    other
    case returns true - including "the object was never there" and "the underlying removal
    itself
    failed", because that inner result is discarded. Do not use the return value to decide
    whether
    an object was actually removed; call BACnetStack_ObjectExists instead.

    C declaration: bool BACnetStack_RemoveObject(const uint32_t deviceInstance, const
    uint16_t objectType, const uint32_t objectInstance)

    Args:
        deviceInstance: (in) The instance of the device that contains the object to remove. [const
            uint32_t deviceInstance]
        objectType: (in) The BACnet object type of the objec to remove. See
            #CASBACnetStack::BACnetObjectType for more info. [const uint16_t objectType]
        objectInstance: (in) The instance of the object to remove. [const uint32_t objectInstance]

    Returns:
        True if successful, false if failed.
    """
    return _lib().BACnetStack_RemoveObject(deviceInstance, objectType, objectInstance)


def BACnetStack_UpdateDeviceInstance(oldDeviceInstance, newDeviceInstance):
    """Changes a device's instance number, in the database and - for a device on a virtual
    network - in the
    virtual router's mapping.

    newDeviceInstance IS NOT RANGE-CHECKED for the main device. Unlike
    BACnetStack_AddDevice, a value
    above 4194302 is accepted and stored while the internal object key silently masks it to
    22 bits,
    leaving the device reporting one instance and keyed under another. Validate the range
    yourself.

    NOT ATOMIC for a device on a virtual network: the database is renamed first, then the
    router mapping.
    If the router mapping is rejected - for example newDeviceInstance is above 4194302,
    which THAT path
    does check - this returns false with the database rename already applied.

    C declaration: bool BACnetStack_UpdateDeviceInstance(const uint32_t oldDeviceInstance,
    const uint32_t newDeviceInstance)

    Args:
        oldDeviceInstance: (in) The instance of the device to change. Must exist. [const uint32_t
            oldDeviceInstance]
        newDeviceInstance: (in) The new device instance. Must not already be in use by another device, and
            must differ from oldDeviceInstance - an update to the same value is rejected.
            [const uint32_t newDeviceInstance]

    Returns:
        True if successful, false if failed. The reason is reported through the
        debug-message callback.
    """
    return _lib().BACnetStack_UpdateDeviceInstance(oldDeviceInstance, newDeviceInstance)


def BACnetStack_UpdateVirtualNetworkNumber(deviceInstance, oldNetworkNumber, newNetworkNumber):
    """Changes a virtual network's number in the virtual router's routing map.

    IT DOES NOT UPDATE THE NETWORK PORT OBJECT. The Network_Number property of the Network
    Port object
    created by BACnetStack_AddVirtualNetwork keeps its old value, so the device advertises
    the old number
    while routing the new one. Write that property yourself if clients read it.

    The device must already be a virtual router - call BACnetStack_AddVirtualNetwork first.

    C declaration: bool BACnetStack_UpdateVirtualNetworkNumber(const uint32_t
    deviceInstance, const uint16_t oldNetworkNumber, const uint16_t newNetworkNumber)

    Args:
        deviceInstance: (in) The device instance of the main device, matching the deviceInstance
            originally passed to BACnetStack_AddVirtualNetwork. [const uint32_t
            deviceInstance]
        oldNetworkNumber: (in) The current network number of the virtual network. Must exist in the
            virtual router. [const uint16_t oldNetworkNumber]
        newNetworkNumber: (in) The new network number for the virtual network. Must not already be in use
            as a virtual network; 0 (local) and 65535 (broadcast) are reserved and rejected.
            [const uint16_t newNetworkNumber]

    Returns:
        True if successful - including the no-op case where oldNetworkNumber equals
        newNetworkNumber. False if deviceInstance does not match the main device, the
        device is not a virtual router, the old number does not exist, the new number is
        a duplicate or reserved, or the stack was built without
        STACK_OPTION_VIRTUAL_ROUTER.
    """
    return _lib().BACnetStack_UpdateVirtualNetworkNumber(
        deviceInstance,
        oldNetworkNumber,
        newNetworkNumber,
    )


