def BACnetStack_SetTrendLogTypeToPolled(
    deviceInstance,
    objectType,
    objectInstance,
    enable,
    stopWhenFull,
    logInterval,
):
    """Sets property values of an existing Trend Log or Trend Log Multiple object.
    This function should only be called after the AddTrendLogObject or
    AddTrendLogMultipleObject functions.

    This function sets the log object to used the polled type of logging and users can
    specify some parameters
    like if it should be enabled, if logging should stop when full, and the log interval.

    C declaration: bool BACnetStack_SetTrendLogTypeToPolled(const uint32_t deviceInstance,
    const uint16_t objectType, const uint32_t objectInstance, const bool enable, const bool
    stopWhenFull, const uint32_t logInterval)

    Args:
        deviceInstance: (in) The instance of the device that contains the Trend Log object. [const
            uint32_t deviceInstance]
        objectType: (in) The type of trend log object. Must be either BACnetObjectType::trendLog or
            BACnetObjectType::trendLogMultiple [const uint16_t objectType]
        objectInstance: (in) The instance of the Trend Log object to update. [const uint32_t
            objectInstance]
        enable: (in) Whether to enable logging on the Trend Log object (true) or not (false).
            [const bool enable]
        stopWhenFull: (in) Whether to stop logging when the log buffer is full (true) or not (false).
            [const bool stopWhenFull]
        logInterval: (in) The periodic interval in hundredths of seconds of when to log values.
            RESOLUTION IS ONE SECOND despite the units: the value is integer-divided by 100
            before use, so a sub-second remainder is discarded (150 behaves as 1.00 s, not
            1.50 s). A value below 100 - including 0 - gives an effective interval of 0 and
            logs on EVERY BACnetStack_Tick(). The value is stored and reported over the wire
            unchanged, so Log_Interval reads back what you passed even when the behaviour is
            rounded down. Not validated. [const uint32_t logInterval]

    Returns:
        True if successful, otherwise false.
    """
    return _lib().BACnetStack_SetTrendLogTypeToPolled(
        deviceInstance,
        objectType,
        objectInstance,
        enable,
        stopWhenFull,
        logInterval,
    )


