def BACnetStack_GetBDTEntry(
    networkPortInstance,
    index,
    ipAddress,
    ipAddressLength,
    subnetMask,
    subnetMaskLength,
):
    """Reads one entry of THIS device's own broadcast distribution table by index. It does not
    read a
    peer's table - use BACnetStack_SendReadBroadcastDistributionTable for that.

    There is NO export that reports the table's size, so the only way to enumerate is to
    read from
    index 0 until this returns false - and that terminating probe LOGS AN ERROR ("Invalid
    index, index
    is out of range") through the debug-message callback on every pass. Indices are
    positions that
    SHIFT after any BACnetStack_DeleteBDTEntry, so re-enumerate from 0 after a delete rather
    than
    continuing an in-flight loop.

    C declaration: uint32_t BACnetStack_GetBDTEntry(const uint32_t networkPortInstance,
    const uint16_t index, uint8_t* ipAddress, const uint8_t ipAddressLength, uint8_t*
    subnetMask, const uint8_t subnetMaskLength)

    Args:
        networkPortInstance: (in) The IPv4 Network Port object instance whose broadcast distribution table is
            being read (#822/#556 Q4). New leading parameter - this used to act on Network
            Port instance 0 implicitly. [const uint32_t networkPortInstance]
        index: (in) The zero-based table position to read. Out of range returns false and logs.
            [const uint16_t index]
        ipAddress: (out) Receives 6 bytes: the 4-octet IPv4 address followed by the 2-octet UDP
            port in BIG-endian order. Must not be NULL. [uint8_t* ipAddress]
        ipAddressLength: (in) EXACT, not a maximum. Must be exactly 6; any other value returns false.
            [const uint8_t ipAddressLength]
        subnetMask: (out) Receives 4 bytes. Must not be NULL. [uint8_t* subnetMask]
        subnetMaskLength: (in) EXACT, not a maximum. Must be exactly 4; any other value returns false.
            [const uint8_t subnetMaskLength]

    Returns:
        The number of bytes written to ipAddress (always ipAddressLength, i.e. 6, on
        success) if an entry exists at the index and was copied out - subnetMask is
        fully written too. 0 if the index is out of range, either pointer is NULL,
        either length is wrong, networkPortInstance does not match any claimed IPv4
        Network Port, or BBMD support was not compiled. (#895: was bool.)
    """
    return _lib().BACnetStack_GetBDTEntry(
        networkPortInstance,
        index,
        ipAddress,
        ipAddressLength,
        subnetMask,
        subnetMaskLength,
    )


def BACnetStack_GetFDTEntry(
    networkPortInstance,
    index,
    ipAddress,
    ipAddressLength,
    timeToLive,
    timeRemaining,
):
    """Reads one entry of THIS device's own foreign device table by index.

    As with BACnetStack_GetBDTEntry there is NO count export, so enumeration means reading
    from index
    0 until this returns false, and that terminating probe LOGS AN ERROR. Indices SHIFT
    after any
    BACnetStack_DeleteFDTEntry and after the BBMD purges an expired registration, so a
    read-then-delete
    loop skips entries unless it re-enumerates from 0 after every delete.

    C declaration: uint32_t BACnetStack_GetFDTEntry(const uint32_t networkPortInstance,
    const uint16_t index, uint8_t* ipAddress, const uint8_t ipAddressLength, uint16_t*
    timeToLive, uint16_t* timeRemaining)

    Args:
        networkPortInstance: (in) The IPv4 Network Port object instance whose foreign device table is being
            read (#822/#556 Q4). New leading parameter. [const uint32_t networkPortInstance]
        index: (in) The zero-based table position to read. Out of range returns false and logs.
            [const uint16_t index]
        ipAddress: (out) Receives 6 bytes: the 4-octet IPv4 address followed by the 2-octet UDP
            port in BIG-endian order. Must not be NULL. [uint8_t* ipAddress]
        ipAddressLength: (in) EXACT, not a maximum. Must be exactly 6; any other value returns false.
            [const uint8_t ipAddressLength]
        timeToLive: (out) Receives the time-to-live, in seconds, the foreign device registered with.
            Must not be NULL. [uint16_t* timeToLive]
        timeRemaining: (out) Receives the time left, in seconds, before this entry expires. Must not be
            NULL. [uint16_t* timeRemaining]

    Returns:
        The number of bytes written to ipAddress (always ipAddressLength, i.e. 6, on
        success) if an entry exists at the index and was copied out - timeToLive and
        timeRemaining are fully written too. 0 if the index is out of range, any pointer
        is NULL, ipAddressLength is not 6, networkPortInstance does not match any
        claimed IPv4 Network Port, or BBMD support was not compiled. (#896: was bool.)
    """
    return _lib().BACnetStack_GetFDTEntry(
        networkPortInstance,
        index,
        ipAddress,
        ipAddressLength,
        timeToLive,
        timeRemaining,
    )


def BACnetStack_AddBDTEntry(
    networkPortInstance,
    ipAddress,
    ipAddressLength,
    subnetMask,
    subnetMaskLength,
):
    """Adds - or REPLACES - an entry in this device's broadcast distribution table.

    TRAP: THE LENGTHS ARE NOT VALIDATED HERE AND A WRONG LENGTH STILL RETURNS TRUE. A length
    below 6
    (address) or 4 (mask) makes the underlying copy refuse, but the refusal is only logged:
    the entry
    is still added with that field left ALL ZEROS, and this function returns true. A length
    above 6 or
    4 is accepted and exactly 6 or 4 bytes are read. Pass exactly 6 and 4, and do not treat
    the return
    value as evidence that the entry is correct - read it back with BACnetStack_GetBDTEntry,
    which does
    enforce exact lengths.

    The table is a set, not a list: adding an entry whose address AND mask both match an
    existing entry
    overwrites it in place rather than appending a duplicate.

    ORDERING: BACnetStack_SetBBMD looks up THIS device's own address in this table and fails
    if it is
    absent. Add the device's own entry with this function FIRST, then call
    BACnetStack_SetBBMD. That
    lookup matches on address only, not address plus mask.

    C declaration: bool BACnetStack_AddBDTEntry(const uint32_t networkPortInstance, const
    uint8_t* ipAddress, const uint8_t ipAddressLength, const uint8_t* subnetMask, const
    uint8_t subnetMaskLength)

    Args:
        networkPortInstance: (in) The IPv4 Network Port object instance whose broadcast distribution table is
            being added to (#822/#556 Q4). New leading parameter. [const uint32_t
            networkPortInstance]
        ipAddress: (in) 6 bytes: the 4-octet IPv4 address followed by the 2-octet UDP port in
            BIG-endian order. NULL is rejected. [const uint8_t* ipAddress]
        ipAddressLength: (in) Pass exactly 6. Not enforced - see the trap above. [const uint8_t
            ipAddressLength]
        subnetMask: (in) 4 bytes. NULL is rejected. [const uint8_t* subnetMask]
        subnetMaskLength: (in) Pass exactly 4. Not enforced - see the trap above. [const uint8_t
            subnetMaskLength]

    Returns:
        True if an entry was added or replaced, INCLUDING the zeroed-field case above.
        False only if either pointer is NULL, networkPortInstance does not match any
        claimed IPv4 Network Port, or BBMD support was not compiled.
    """
    return _lib().BACnetStack_AddBDTEntry(
        networkPortInstance,
        ipAddress,
        ipAddressLength,
        subnetMask,
        subnetMaskLength,
    )


